(()=>{const c=new OffscreenCanvas(4,4),x=c.getContext('2d',{willReadFrequently:true});x.fillStyle='white';x.fillRect(0,0,4,4);x.fillStyle='black';x.beginPath();x.arc(1.5,1.5,1.2,0,Math.PI*2);x.fill();const a=x.getImageData(0,0,4,4).data,b=x.getImageData(0,0,4,4).data,cut=x.getImageData(1,1,2,2).data;const overlap=[...cut].every((v,i)=>v===a[((Math.floor(i/4/2)+1)*4+Math.floor(i/4)%2+1)*4+i%4]);const partial=[...a].filter((v,i)=>i%4!==3&&v>0&&v<255).length;const copy=new OffscreenCanvas(4,4),y=copy.getContext('2d',{willReadFrequently:true});y.drawImage(c,0,0);const copied=[...a].every((v,i)=>v===y.getImageData(0,0,4,4).data[i]);x.fillStyle='red';x.fillRect(3,3,1,1);const after=x.getImageData(0,0,4,4).data;return {partial:partial>0,repeat:[...a].every((v,i)=>v===b[i]),overlap,copied,local:[...a].slice(0,60).every((v,i)=>v===after[i]),opaque:[...a].every((v,i)=>i%4!==3||v===255)}})()